'use strict';
(()=>{
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const route=p=>window.EcoPlatform?.url('crm',p)||new URL(p,document.baseURI).href;
 let session;try{session=JSON.parse(sessionStorage.getItem('ecocharge-entry:staff')||'null');}catch{}
 const role=session?.role==='ftd'?'ftd':['admin','staff'].includes(session?.role)?'admin':null;
 if(!role){location.replace(route('team/?next=crm'));return;}
 const actor=session.user||role;
 const read=()=>{let raw;try{raw=JSON.parse(localStorage.getItem(EcoCrmStore.key)||'null');}catch{}const a=EcoCrmStore.normalize(raw);EcoFunding.removePendingFees(a);return a;};
 const write=a=>{localStorage.setItem(EcoCrmStore.key,JSON.stringify(a));render();};
 const cash=n=>new Intl.NumberFormat(window.EcoLocale?.locale||'en-US',{style:'currency',currency:'USD'}).format(n);
 const date=v=>new Intl.DateTimeFormat(window.EcoLocale?.locale||'en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));
 let current=read(),operation=null,profileVersion=null,active='client';
 const t=s=>window.EcoLocale?.t(s)||s;
 function toast(s){$('#crm-toast').textContent=t(s);$('#crm-toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#crm-toast').classList.remove('visible'),4000);}
 function open(html){$('#crm-dialog-body').innerHTML=html;window.EcoLocale?.localize($('#crm-dialog-body'));if(!$('#crm-dialog').open)$('#crm-dialog').showModal();$('#crm-dialog').scrollTop=0;}
 function close(){operation=null;$('#crm-dialog').close();}
 function facts(a){const p=a.plan||a.planDraft;return `<dl class="crm-facts"><div><dt>Email</dt><dd translate="no">${esc(a.client.email||'—')}</dd></div><div><dt>Phone</dt><dd translate="no">${esc(a.acquisition?.phone||'—')}</dd></div><div><dt>Traffic source</dt><dd translate="no">${esc([a.attribution?.utm_source,a.attribution?.utm_campaign,a.attribution?.landing_id,a.attribution?.landing_host].filter(Boolean).join(' / ')||'—')}</dd></div><div><dt>Plan amount</dt><dd translate="no">${p?cash(p.capital):'—'}</dd></div></dl>`;}
 function requests(a){const pending=a.requests.filter(r=>r.type==='topup'&&r.status==='Pending');return `<section class="crm-panel"><div class="crm-section-title"><h2>Funding requests</h2><span>${pending.length}</span></div>${pending.length?pending.map(r=>`<article class="crm-request"><div><strong translate="no">${cash(r.amount)}</strong><span>${r.payment?.method==='crypto'?esc(r.payment.asset+' / '+r.payment.network):r.payment?.method==='card'?'Card':'Funding request'}</span><small translate="no">${esc(r.id)}</small></div><button class="crm-button primary" data-request="${esc(r.id)}">Review & credit</button></article>`).join(''):'<p class="crm-empty">No pending funding requests.</p>'}</section>`;}
 function history(a){const rows=(a.adjustments||[]).slice(0,30);return `<section class="crm-panel"><div class="crm-section-title"><h2>Balance change history</h2><span>${rows.length}</span></div>${rows.length?`<div class="crm-history">${rows.map(r=>{const delta=r.after.balance-r.before.balance;return `<article><div><strong translate="no">${delta>0?'+':''}${cash(delta)}</strong><time translate="no">${date(r.date)}</time></div><p translate="no">${esc(r.reason)}</p><div class="crm-history-detail"><span translate="no">${esc(r.actor)}</span><span translate="no">${cash(r.before.balance)} → ${cash(r.after.balance)}</span></div></article>`}).join('')}</div>`:'<p class="crm-empty">Balance changes will appear here with the amount, reason and employee.</p>'}</section>`;}
 function render(){current=read();const a=current,s=EcoFunding.state(a);$('#crm-content').innerHTML=`<div class="crm-page-heading"><div><span class="crm-eyebrow">FTD / CLIENT WORKSPACE</span><h1>Client. Balance. Next action.</h1></div>${role==='admin'?`<a class="crm-text" href="${esc(route('staff/'))}">Administrator workspace ↗</a>`:''}</div><div class="crm-layout"><aside class="crm-client-list"><h2>My clients</h2><button class="crm-selected" data-crm-tab="client"><span class="crm-avatar" translate="no">${esc(a.client.name.slice(0,1))}</span><span><strong translate="no">${esc(a.client.name)}</strong><small>CL-1001</small></span><b>→</b></button><p>1 linked sample account</p></aside><div class="crm-client-body"><section class="crm-client-head"><div><span class="crm-eyebrow">CL-1001</span><h2 translate="no">${esc(a.client.name)}</h2></div><span class="crm-status">${s.hasFirstDeposit?'First deposit confirmed':s.pending.length?'Payment awaiting review':'Before first deposit'}</span></section><section class="crm-balance-card"><div><span>Available balance</span><strong translate="no">${cash(Math.max(0,a.balance-EcoCrmStore.reserved(a)))}</strong>${EcoCrmStore.reserved(a)?`<small><span>Reserved for withdrawals:</span> <b translate="no">${cash(EcoCrmStore.reserved(a))}</b></small>`:''}</div><div class="crm-main-actions"><button class="crm-button primary" data-operation="credit">+ <span>Credit balance</span></button><button class="crm-button secondary" data-operation="debit">− <span>Debit balance</span></button><button class="crm-button outline" id="crm-edit-client">Edit client details</button></div></section><nav class="crm-tabs" aria-label="Client information">${[['client','Client details'],['requests','Funding requests'],['history','Change history']].map(([id,label])=>`<button data-crm-tab="${id}" aria-current="${active===id?'page':'false'}">${label}${id==='requests'&&s.pending.length?` <b>${s.pending.length}</b>`:''}</button>`).join('')}</nav>${active==='client'?`<section class="crm-panel">${facts(a)}<div class="crm-note"><h3>Staff note</h3><p translate="no">${esc(a.client.note||'')}</p>${a.client.note?'':'<small>No staff note yet.</small>'}</div></section>${s.pending.length?requests(a):''}`:active==='requests'?requests(a):history(a)}</div></div>`;window.EcoLocale?.localize($('#crm-content'));}
 function begin(kind,requestId){current=read();const request=requestId?current.requests.find(r=>r.id===requestId&&r.status==='Pending'&&r.type==='topup'):null;if(requestId&&!request){toast('This funding request has changed or was already reviewed.');render();return;}
  operation={id:'FTD-'+crypto.randomUUID(),kind,requestId:request?.id||null,expectedBalance:current.balance,actor,role};
  open(`<h2 id="crm-dialog-title">${kind==='credit'?'Credit client balance':'Debit client balance'}</h2><p><span>Client:</span> <strong translate="no">${esc(current.client.name)}</strong></p><form id="crm-operation-form"><label for="crm-amount">Amount (USD)</label><input id="crm-amount" type="number" inputmode="decimal" min="0.01" max="10000000" step="0.01" value="${request?.amount||''}" ${request?'readonly':''} required><label for="crm-reason">Reason / payment reference</label><input id="crm-reason" maxlength="250" minlength="3" required value="${request?esc(request.id):''}"><p class="crm-form-note">${kind==='credit'?'Crediting records a confirmed sample deposit. No card or wallet is charged.':'Debiting changes the account balance. It does not send a withdrawal or change its schedule.'}</p><div class="crm-error" id="crm-error" role="alert"></div><button class="crm-button primary" type="submit">Review balance change</button></form>`);$('#crm-amount').focus();
 }
 function edit(){current=read();profileVersion=JSON.stringify([current.client,current.acquisition]);open(`<h2 id="crm-dialog-title">Edit client details</h2><form id="crm-profile-form"><label for="crm-name">Client name</label><input id="crm-name" maxlength="100" minlength="2" required value="${esc(current.client.name)}"><label for="crm-email">Email</label><input id="crm-email" type="email" maxlength="160" required value="${esc(current.client.email)}"><label for="crm-phone">Phone</label><input id="crm-phone" type="tel" maxlength="40" value="${esc(current.acquisition?.phone||'')}"><label for="crm-note">Staff note</label><textarea id="crm-note" rows="4" maxlength="2000">${esc(current.client.note||'')}</textarea><p class="crm-form-note">Internal notes. Saving does not send a message to the client.</p><div class="crm-error" id="crm-error" role="alert"></div><button class="crm-button primary" type="submit">Save client details</button></form>`);}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.operation)begin(b.dataset.operation);if(b.dataset.request)begin('credit',b.dataset.request);if(b.dataset.crmTab){active=b.dataset.crmTab;render();}if(b.id==='crm-edit-client')edit();if(b.id==='crm-close')close();if(b.id==='crm-signout'){sessionStorage.removeItem('ecocharge-entry:staff');location.assign(route('team/'));}if(b.id==='crm-confirm'){
   if(!operation)return;try{const a=read();EcoCrmStore.changeBalance(a,operation);write(a);close();active='history';render();toast('Balance change saved.');}catch(error){$('#crm-error').textContent=t(error.message);}
  }});
 document.addEventListener('submit',e=>{if(e.target.id==='crm-operation-form'){e.preventDefault();if(!operation)return;const amount=Number($('#crm-amount').value),reason=$('#crm-reason').value.trim();try{const candidate={...operation,amount,reason};EcoCrmStore.changeBalance(structuredClone(read()),candidate);operation=candidate;const next=Math.round((operation.expectedBalance+(operation.kind==='credit'?amount:-amount))*100)/100;open(`<h2 id="crm-dialog-title">Confirm balance change</h2><dl class="crm-review"><div><dt>Current balance</dt><dd translate="no">${cash(operation.expectedBalance)}</dd></div><div><dt>${operation.kind==='credit'?'Credit':'Debit'}</dt><dd translate="no">${cash(amount)}</dd></div><div><dt>New balance</dt><dd translate="no">${cash(next)}</dd></div></dl><p translate="no">${esc(reason)}</p><div class="crm-error" id="crm-error" role="alert"></div><button id="crm-confirm" class="crm-button primary">Confirm change</button>`);}catch(error){$('#crm-error').textContent=t(error.message);}}
  if(e.target.id==='crm-profile-form'){e.preventDefault();try{const a=read();if(profileVersion!==JSON.stringify([a.client,a.acquisition]))throw Error('Client details changed in another tab. Reopen the form.');const name=$('#crm-name').value.trim(),email=$('#crm-email').value.trim();if(name.length<2||!email)throw Error('Enter the client name and a valid email.');a.client={...a.client,name,email,note:$('#crm-note').value.trim()};a.acquisition={...a.acquisition,phone:$('#crm-phone').value.trim()};a.activity.unshift({date:new Date().toISOString(),text:actor+': updated client details'});write(a);close();toast('Client details saved.');}catch(error){$('#crm-error').textContent=t(error.message);}}
 });
 window.addEventListener('storage',e=>{if(e.key===EcoCrmStore.key){render();toast('Client account updated.');}});document.addEventListener('ecocharge:locale',render);render();
})();
